// InterfaceSettings defines model for InterfaceSettings.
type InterfaceSettings struct {
	// AdvertisedAddress Address clients use to reach this server (matters with several NICs or
	// NAT). Null uses the interface's primary IPv4 address. Boot image
	// `serverUrls` default from this.
	AdvertisedAddress *string `json:"advertisedAddress"`
	Dhcp              struct {
		// ListenOn67 `proxy` only. Set false when a real DHCP server on this same host owns
		// UDP 67; the proxy then uses 4011 only, so clients only find it if that
		// server sends option 60 `PXEClient`. On Linux, don't share 67 with
		// another DHCP server even if the bind succeeds: `SO_REUSEPORT` would
		// split packets between the two at random.
		ListenOn67 *bool `json:"listenOn67,omitempty"`

		// Mode `off`: no DHCP; see `externalDhcpGuidance` for what to configure on
		// your own server. `proxy`: answers PXE/HTTP boot clients only, never
		// assigns addresses. `full`: address pool with persisted leases.
		Mode InterfaceSettingsDhcpMode `json:"mode"`

		// Pool Required for `full`.
		Pool *struct {
			DnsServers   *[]string `json:"dnsServers,omitempty"`
			DomainName   *string   `json:"domainName"`
			End          string    `json:"end"`
			LeaseSeconds *int      `json:"leaseSeconds,omitempty"`

			// PingCheck Ping an address before offering it.
			PingCheck  *bool   `json:"pingCheck,omitempty"`
			Router     *string `json:"router"`
			Start      string  `json:"start"`
			SubnetMask string  `json:"subnetMask"`
		} `json:"pool"`
	} `json:"dhcp"`

	// ExternalDhcpGuidance For `off` mode, the options to set on an external DHCP server, per architecture.
	ExternalDhcpGuidance *[]struct {
		// Arch Derived from DHCP option 93. `uefi-x64` = 7/9, `uefi-x64-http` = 16,
		// `uefi-arm64` = 11, `uefi-arm64-http` = 19, `bios` = 0.
		Arch *ClientArch `json:"arch,omitempty"`

		// BootFile Option 67 (a URL for HTTP boot).
		BootFile *string `json:"bootFile,omitempty"`

		// NextServer Option 66 / siaddr.
		NextServer *string `json:"nextServer,omitempty"`

		// VendorClass Option 60 value to return (PXEClient or HTTPClient).
		VendorClass *string `json:"vendorClass,omitempty"`
	} `json:"externalDhcpGuidance,omitempty"`

	// MacPrefixes Optional allow-list. When non-empty, only clients whose MAC starts with one
	// of these prefixes (e.g. an OUI, `00:1b:21`) are answered on this
	// interface. Empty answers every PXE client. Applies to DHCP `proxy` and
	// `full`; with `off` the external DHCP server decides.
	MacPrefixes *[]string `json:"macPrefixes,omitempty"`

	// Name OS interface name, e.g. `Ethernet 2` or `enp3s0`.
	Name     string `json:"name"`
	Services struct {
		Http      *bool `json:"http,omitempty"`
		HttpPort  *int  `json:"httpPort,omitempty"`
		Https     *bool `json:"https,omitempty"`
		HttpsPort *int  `json:"httpsPort,omitempty"`
		Tftp      *bool `json:"tftp,omitempty"`
	} `json:"services"`
}

